assert re.search(pattern,s,re.S);s=re.sub(pattern,lambda m:block,s,count=1,flags=re.S);s=s.replace('</head>','<link rel="stylesheet" href="../../assets/delivery-story.css?v=20261107-local"></head>');p.write_text(s,encoding='utf8')
